void ImagesCache<Image>::setFullResolution(bool on)
{
    // cheshire (step 6d): initIC's cache size at the full-resolution image size
    _fullResolution = on;
    const float s = on ? float(_mp.getProcessDownscale()) : 1.0f;
    const float oneimagemb = (sizeof(Color) * _mp.getMaxImageWidth() * _mp.getMaxImageHeight()) / 1024.f / 1024.f * s * s;
    const float maxmbCPU = (float)_mp.userParams.get<int>("images_cache.maxmbCPU", 5000);
    int npreload = (int)(maxmbCPU / oneimagemb);
    if (npreload < 5)
        npreload = 5;
    if (npreload > _mp.ncams)
        npreload = _mp.ncams;
    setCacheSize(npreload);
}

